using Cave.Axioms.Mastery;
namespace Cave.Domain { public static class DomainAuthoringEligibilityVerification { public static bool TryRunAll(out string failure) { var p=PlayerMasteryPolicy.Default; var s=PlayerMasteryEvidenceState.Empty; foreach(MasteryEvidenceDimension d in (MasteryEvidenceDimension[])System.Enum.GetValues(typeof(MasteryEvidenceDimension)))s=s.Submit(new PhenomenonMasteryEvidenceSubmission(LawPhenomenon.Heat,d,1,true,LawExpression.Projectile),p); DomainLaw l;LawValidationResult v;DomainLaw.TryCreate(LawExpression.Projectile,LawPhenomenon.Heat,LawTerritoryPrinciple.Propagation,out l,out v); var x=new DomainAuthoringContext(true,s,1,p,DomainComplexityPolicy.Default);var ok=DomainAuthoringEligibility.Evaluate(DomainComposition.Empty,l,x);var noSeed=DomainAuthoringEligibility.Evaluate(DomainComposition.Empty,l,new DomainAuthoringContext(false,s,1,p,DomainComplexityPolicy.Default));var neg=DomainAuthoringEligibility.Evaluate(DomainComposition.Empty,l,new DomainAuthoringContext(true,s,-1,p,DomainComplexityPolicy.Default));var zero=DomainAuthoringEligibility.Evaluate(DomainComposition.Empty,l,new DomainAuthoringContext(true,s,0,p,DomainComplexityPolicy.Default));var dup=DomainAuthoringEligibility.Evaluate(ok.Proposed,l,new DomainAuthoringContext(true,s,9,p,DomainComplexityPolicy.Default)); bool pass=ok.IsEligible&&ok.Current.Count==0&&noSeed.RejectionReason==DomainAuthoringRejectionReason.DomainSeedRequired&&neg.RejectionReason==DomainAuthoringRejectionReason.InvalidComplexityCapacity&&zero.RejectionReason==DomainAuthoringRejectionReason.ComplexityCapacityExceeded&&dup.RejectionReason==DomainAuthoringRejectionReason.DuplicateLaw; failure=pass?null:"Authoring gate boundary failed.";return pass;} } }
